actions.script:
boolean showArchived = (includeArchived == "Y" || includeArchived == true)

// Recursive message builder for a discussion container
def buildMessageTree
buildMessageTree = { String discId, String parentMsgId ->
    def msgFind = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
        .condition("discussionId", discId)
        .condition("senderRoleEnumId", "not-equals", "AsrAssistant")

    if (!showArchived) {
        msgFind.condition("statusId", "not-equals", "AmsArchived")
    }

    if (parentMsgId) {
        msgFind.condition("parentMessageId", parentMsgId)
    } else {
        msgFind.condition("parentMessageId", null)
    }
    def messages = msgFind.orderBy("entryDate").list()

    return messages.collect { msg ->
        String mId = msg.messageId as String
        def contents = ec.entity.find("org.moqui.ai.discussion.AgiMessageContent")
            .condition("messageId", mId)
            .list()
        def titledContent = contents?.find { (it.title as boolean) }
        String displayTitle = titledContent?.title ?: (contents ? (contents[0].bodyText?.take(45) + "...") : "Topic #" + mId)

        // Check if this turn or an assistant response attached to it has a stagedPayloadId
        String activePayloadId = msg.stagedPayloadId
        if (!activePayloadId) {
            def asstWithPayload = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
                .condition("parentMessageId", mId)
                .condition("senderRoleEnumId", "AsrAssistant")
                .condition("stagedPayloadId", "not-equals", null)
                .one()
            activePayloadId = asstWithPayload?.stagedPayloadId
        }

        String lowerTitle = displayTitle.toLowerCase()
        boolean isPlanTurn = !!activePayloadId || lowerTitle.contains("plan:") || lowerTitle.contains("subplan")

        return [
            nodeKey              : "msg_" + mId,
            id                   : mId,
            messageId            : mId,
            discussionId         : discId,
            parentMessageId      : msg.parentMessageId,
            label                : displayTitle,
            senderRoleEnumId     : msg.senderRoleEnumId,
            statusId             : msg.statusId,
            isArchived           : (msg.statusId == "AmsArchived"),
            stagedPayloadId      : activePayloadId,
            mode                 : (isPlanTurn ? "plan" : "discuss"),
            children             : buildMessageTree(discId, mId)
        ]
    }
}

// Query root discussion containers
def discFind = ec.entity.find("org.moqui.ai.discussion.AgiDiscussion")
if (discussionId) {
    discFind.condition("discussionId", discussionId)
} else {
    if (targetComponent) discFind.condition("targetComponent", targetComponent)
    if (targetArtifactUri) discFind.condition("targetArtifactUri", targetArtifactUri)
}

if (!showArchived) {
    discFind.condition("statusId", "not-equals", "AgdStatusArchived")
}

def discussions = discFind.orderBy("discussionId").list()

context.treeNodes = discussions.collect { disc ->
    String dId = disc.discussionId as String

    def dFacets = ec.entity.find("org.moqui.ai.discussion.AgiDiscussionFacet")
        .condition("discussionId", dId)
        .list()

    def rels = ec.entity.find("org.moqui.ai.discussion.AgiDiscussionRelationship")
        .condition("parentDiscussionId", dId)
        .list()
    def relatedDiscIds = rels*.childDiscussionId?.findAll { it != null }

    List childDiscNodes = []
    if (relatedDiscIds && !relatedDiscIds.isEmpty()) {
        def childDiscsFind = ec.entity.find("org.moqui.ai.discussion.AgiDiscussion")
            .condition("discussionId", "in", relatedDiscIds)
        if (!showArchived) {
            childDiscsFind.condition("statusId", "not-equals", "AgdStatusArchived")
        }
        def childDiscs = childDiscsFind.list()
        childDiscNodes = childDiscs.collect { cd ->
            [
                nodeKey              : "disc_" + cd.discussionId,
                id                   : cd.discussionId,
                discussionId         : cd.discussionId,
                label                : "🔗 " + cd.name,
                shortName            : cd.shortName,
                statusId             : cd.statusId,
                isArchived           : (cd.statusId == "AgdStatusArchived"),
                discussionTypeEnumId : cd.discussionTypeEnumId,
                targetComponent      : cd.targetComponent,
                targetArtifactUri    : cd.targetArtifactUri,
                isRelationshipNode   : true,
                children             : buildMessageTree(cd.discussionId as String, null)
            ]
        }
    }

    List messageChildren = buildMessageTree(dId, null)

    return [
        nodeKey              : "disc_" + dId,
        id                   : dId,
        discussionId         : dId,
        label                : disc.name ?: ("Discussion #" + dId),
        shortName            : disc.shortName,
        statusId             : disc.statusId,
        isArchived           : (disc.statusId == "AgdStatusArchived"),
        discussionCategoryEnumId: disc.discussionCategoryEnumId,
        discussionTypeEnumId : disc.discussionTypeEnumId,
        targetComponent      : disc.targetComponent,
        targetArtifactUri    : disc.targetArtifactUri,
        promotedWorkEffortId : disc.promotedWorkEffortId,
        messageCount         : disc.messageCount ?: 0,
        facets               : dFacets*.getMap(),
        children             : (childDiscNodes + messageChildren)
    ]
}

def newDisc = ec.entity.makeValue("org.moqui.ai.discussion.AgiDiscussion") newDisc.name = name newDisc.shortName = shortName ?: (name.take(20)) newDisc.targetComponent = targetComponent newDisc.targetArtifactUri = targetArtifactUri newDisc.discussionCategoryEnumId = discussionCategoryEnumId newDisc.discussionTypeEnumId = discussionTypeEnumId newDisc.statusId = "AgdStatusActive" newDisc.fromDate = ec.user.nowTimestamp newDisc.messageCount = 0 newDisc.setSequencedIdPrimary() newDisc.create()
context.discussionId = newDisc.discussionId
if (facets instanceof Map) { facets.each { k, v -> if (k && v) { ec.entity.makeValue("org.moqui.ai.discussion.AgiDiscussionFacet") .set("discussionId", newDisc.discussionId) .set("facetKey", k.toString().trim()) .set("facetValue", v.toString().trim()) .set("facetTypeEnumId", "AftDirective") .setSequencedIdPrimary() .create() } } }

def dFacets = ec.entity.find("org.moqui.ai.discussion.AgiDiscussionFacet") .condition("discussionId", discussionId) .list() Map fMap = [:] dFacets.each { fMap[it.facetKey] = it.facetValue } context.containerFacets = fMap
def msgList = ec.entity.find("org.moqui.ai.discussion.AgiMessage") .condition("discussionId", discussionId) .orderBy("entryDate") .list()
context.messages = msgList.collect { m -> def contents = ec.entity.find("org.moqui.ai.discussion.AgiMessageContent") .condition("messageId", m.messageId) .orderBy("contentSeqId") .list() def mFacets = ec.entity.find("org.moqui.ai.discussion.AgiMessageFacet") .condition("messageId", m.messageId) .list()
String bodyText = contents ? contents*.bodyText.join("\n\n") : ""
[ messageId : m.messageId, parentMessageId : m.parentMessageId, senderRoleEnumId : m.senderRoleEnumId, role : m.senderRoleEnumId == "AsrAssistant" ? "assistant" : "user", partyId : m.partyId, statusId : m.statusId, targetArtifactUri : m.targetArtifactUri, targetMariaId : m.targetMariaId, promotedWorkEffortId : m.promotedWorkEffortId, stagedPayloadId : m.stagedPayloadId, entryDate : m.entryDate?.toString(), content : bodyText, contents : contents*.getMap(), facets : mFacets*.getMap() ] }

String authorPartyId = senderRoleEnumId == "AsrAssistant" ? null : (ec.user.userId ?: null)
def newMsg = ec.entity.makeValue("org.moqui.ai.discussion.AgiMessage") newMsg.discussionId = discussionId newMsg.parentMessageId = parentMessageId ?: null newMsg.senderRoleEnumId = senderRoleEnumId newMsg.partyId = authorPartyId newMsg.statusId = "AmsActive" newMsg.targetArtifactUri = targetArtifactUri newMsg.targetMariaId = targetMariaId newMsg.entryDate = ec.user.nowTimestamp newMsg.setSequencedIdPrimary() newMsg.create()
context.messageId = newMsg.messageId
ec.entity.makeValue("org.moqui.ai.discussion.AgiMessageContent") .set("messageId", newMsg.messageId) .set("contentSeqId", "1") .set("contentTypeEnumId", contentTypeEnumId) .set("title", title ?: (content.take(40))) .set("bodyText", content) .create()
if (facets instanceof Map) { facets.each { k, v -> if (k && v) { ec.entity.makeValue("org.moqui.ai.discussion.AgiMessageFacet") .set("messageId", newMsg.messageId) .set("facetKey", k.toString().trim()) .set("facetValue", v.toString().trim()) .set("facetTypeEnumId", "AftDirective") .set("isInheritable", "Y") .setSequencedIdPrimary() .create() } } }
def disc = ec.entity.find("org.moqui.ai.discussion.AgiDiscussion") .condition("discussionId", discussionId) .one() if (disc) { disc.messageCount = (disc.messageCount ?: 0) + 1 disc.lastActivityDate = ec.user.nowTimestamp disc.update() }

import org.moqui.resource.ResourceReference

def disc = ec.entity.find("org.moqui.ai.discussion.AgiDiscussion")
    .condition("discussionId", discussionId)
    .one()
if (!disc) { ec.message.addError("Discussion ${discussionId} not found"); return }

String comp = disc.targetComponent ?: "nursinghome"
String artUri = disc.targetArtifactUri ?: ""
String effectiveMode = (mode ?: "discuss").toLowerCase().trim()

def dFacets = ec.entity.find("org.moqui.ai.discussion.AgiDiscussionFacet")
    .condition("discussionId", discussionId)
    .list()
Map mergedFacets = [:]
dFacets.each { mergedFacets[it.facetKey] = it.facetValue }

def loadFirstExisting = { List<String> paths ->
    for (String path : paths) {
        try {
            ResourceReference rr = ec.resource.getLocationReference(path)
            if (rr != null && rr.getExists()) {
                ec.logger.info("📄 [dispatch#AgentTurn] Loaded instruction layer from: ${path}")
                return rr.getText()
            }
        } catch (Exception ignore) {}
    }
    return null
}

StringBuilder systemInstruction = new StringBuilder()

String baseFoundation = loadFirstExisting([
    "component://agi-ide/mcp/instructions/base/system-foundation.md",
    "component://agi-ai/mcp/instructions/base/system-foundation.md"
])
if (baseFoundation) systemInstruction.append(baseFoundation.trim()).append("\n\n")

String guardrails = loadFirstExisting([
    "component://agi-ide/mcp/instructions/base/guardrails.md",
    "component://agi-ai/mcp/instructions/base/guardrails.md"
])
if (guardrails) systemInstruction.append(guardrails.trim()).append("\n\n")

String domainDirectives = loadFirstExisting([
    "component://${comp}/mcp/instructions/domain-instructions.md",
    "component://${comp}/mcp/instructions/${comp}-domain.md"
])
if (domainDirectives) {
    systemInstruction.append("<!-- ============================================================= -->\n")
    systemInstruction.append("<!-- DOMAIN DIRECTIVES: ${comp.toUpperCase()} -->\n")
    systemInstruction.append("<!-- ============================================================= -->\n")
    systemInstruction.append(domainDirectives.trim()).append("\n\n")
}

String specificInstruction = null
if (instructionName) {
    specificInstruction = loadFirstExisting([
        "component://${comp}/mcp/instructions/${instructionName}",
        "component://agi-ide/mcp/instructions/${instructionName}",
        "component://agi-ide/mcp/instructions/artifacts/generic/${instructionName}"
    ])
}

if (!specificInstruction) {
    String artifactCategory = "generic"
    if (artUri.contains("/screen/") || artUri.endsWith(".xml")) artifactCategory = "screen"
    else if (artUri.contains("/service/") || artUri.contains("Services.xml")) artifactCategory = "service"
    else if (artUri.contains("/entity/") || artUri.contains("Entities.xml")) artifactCategory = "entity"

    specificInstruction = loadFirstExisting([
        "component://agi-ide/mcp/instructions/artifacts/${artifactCategory}/${effectiveMode}.md",
        "component://agi-ide/mcp/instructions/artifacts/generic/${effectiveMode}.md",
        "component://agi-ide/mcp/instructions/architect-evaluation.md"
    ])
}

if (specificInstruction) {
    systemInstruction.append("<!-- ============================================================= -->\n")
    systemInstruction.append("<!-- PROMPT & MODE DIRECTIVE: ${effectiveMode.toUpperCase()} -->\n")
    systemInstruction.append("<!-- ============================================================= -->\n")
    systemInstruction.append(specificInstruction.trim()).append("\n\n")
}

List conversationHistory = []
if (parentMessageId) {
    List threadMessages = []
    String currentTraceId = parentMessageId
    Set visited = new HashSet()
    int depthGuard = 0

    while (currentTraceId && depthGuard < 12 && !visited.contains(currentTraceId)) {
        visited.add(currentTraceId)
        depthGuard++
        def traceMsg = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
            .condition("messageId", currentTraceId)
            .one()
        if (!traceMsg) break

        def contents = ec.entity.find("org.moqui.ai.discussion.AgiMessageContent")
            .condition("messageId", traceMsg.messageId)
            .orderBy("contentSeqId")
            .list()
        String text = contents ? contents*.bodyText.join("\n\n") : ""

        if (text.trim().startsWith("{") && text.trim().endsWith("}")) {
            try {
                def parsed = new groovy.json.JsonSlurper().parseText(text)
                text = parsed.message ?: parsed.architectureSummary ?: text
            } catch (Exception ignore) {}
        }

        if (text && text.trim()) {
            String msgRole = traceMsg.senderRoleEnumId == "AsrAssistant" ? "assistant" : "user"
            threadMessages.add(0, [role: msgRole, content: text.trim()])
        }

        currentTraceId = traceMsg.parentMessageId
    }

    if (threadMessages.size() <= 1) {
        def recentTurns = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
            .condition("discussionId", discussionId)
            .orderBy("-entryDate")
            .limit(6)
            .list()
            .reverse()

        threadMessages = []
        recentTurns.each { rMsg ->
            if (rMsg.messageId != parentMessageId) {
                def rConts = ec.entity.find("org.moqui.ai.discussion.AgiMessageContent")
                    .condition("messageId", rMsg.messageId)
                    .list()
                String rText = rConts ? rConts*.bodyText.join("\n\n") : ""
                if (rText.trim().startsWith("{") && rText.trim().endsWith("}")) {
                    try {
                        def parsed = new groovy.json.JsonSlurper().parseText(rText)
                        rText = parsed.message ?: parsed.architectureSummary ?: rText
                    } catch (Exception ignore) {}
                }
                if (rText && rText.trim()) {
                    String rRole = rMsg.senderRoleEnumId == "AsrAssistant" ? "assistant" : "user"
                    threadMessages.add([role: rRole, content: rText.trim()])
                }
            }
        }
    }

    conversationHistory = threadMessages
    ec.logger.info("🧵 [dispatch#AgentTurn] Ingested ${conversationHistory.size()} historical turns for context.")
}

Map proxyParams = [
    mode                : effectiveMode,
    userPrompt          : userPrompt,
    conversationHistory : conversationHistory,
    targetComponent     : comp,
    artifactUri         : artUri,
    facets              : mergedFacets
]

Map turnResult = ec.service.sync()
    .name("org.moqui.ai.AgiAiGatewayServices.run#OpenAiProxy")
    .parameters(proxyParams)
    .call()

String agentReply = turnResult?.completionText ?: "Unable to complete assessment."
context.completionText = agentReply

Map recResult = ec.service.sync()
    .name("org.moqui.ai.discussion.AgiDiscussionServices.record#DiscussionTurn")
    .parameters([
        discussionId      : discussionId,
        parentMessageId   : parentMessageId,
        senderRoleEnumId  : "AsrAssistant",
        content           : agentReply,
        title             : effectiveMode == "plan" ? "Architecture Plan" : "AI Response",
        targetArtifactUri : artUri
    ])
    .call()

String asstMsgId = recResult.messageId
context.assistantMessageId = asstMsgId
context.stagedPayloadId = null

if (effectiveMode == "plan" && asstMsgId) {
    try {
        String payloadJson = null
        String planTitle = "Architecture Plan: " + (disc.name ?: comp)

        if (agentReply.trim().startsWith("{") && agentReply.trim().endsWith("}")) {
            try {
                def parsedJson = new groovy.json.JsonSlurper().parseText(agentReply)
                if (parsedJson.astTree || parsedJson.files || parsedJson.plan) {
                    payloadJson = agentReply.trim()
                } else if (parsedJson.message) {
                    def innerMatcher = parsedJson.message =~ /(?s)```json\s*(\{.*?\})\s*```/
                    if (innerMatcher.find()) {
                        payloadJson = innerMatcher.group(1).trim()
                    }
                }
            } catch (Exception ignore) {}
        }

        if (!payloadJson) {
            def jsonFenceMatcher = agentReply =~ /(?s)```json\s*(\{.*?\})\s*```/
            if (jsonFenceMatcher.find()) {
                payloadJson = jsonFenceMatcher.group(1).trim()
            }
        }

        if (!payloadJson) {
            payloadJson = groovy.json.JsonOutput.toJson([
                mode           : "plan",
                planType       : "ARCHITECTURAL_BLUEPRINT",
                targetComponent: comp,
                artifactUri    : artUri,
                planDetails    : agentReply
            ])
        }

        def newPayload = ec.entity.makeValue("org.moqui.ai.payload.AgiPayload")
        newPayload.modeEnumId = "AamPlan"
        newPayload.statusId = "PlsDraft"
        newPayload.targetComponent = comp
        newPayload.artifactUri = artUri
        newPayload.discussionId = discussionId
        newPayload.messageId = asstMsgId
        newPayload.title = planTitle
        newPayload.userPromptText = userPrompt
        newPayload.payloadJsonData = payloadJson
        newPayload.createdDate = ec.user.nowTimestamp
        newPayload.setSequencedIdPrimary()
        newPayload.create()

        context.stagedPayloadId = newPayload.agiPayloadId

        // Link stagedPayloadId to assistant message
        def msgVal = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
            .condition("messageId", asstMsgId)
            .one()
        if (msgVal) {
            msgVal.stagedPayloadId = newPayload.agiPayloadId
            msgVal.update()
        }

        // Also link stagedPayloadId to parent user prompt message
        if (parentMessageId) {
            def parentUserMsg = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
                .condition("messageId", parentMessageId)
                .one()
            if (parentUserMsg && !parentUserMsg.stagedPayloadId) {
                parentUserMsg.stagedPayloadId = newPayload.agiPayloadId
                parentUserMsg.update()
            }
        }

        ec.logger.info("📦 [dispatch#AgentTurn] Created AgiPayload #${newPayload.agiPayloadId} linked to AgiMessage #${asstMsgId}")
    } catch (Exception ex) {
        ec.logger.error("Failed to persist plan AgiPayload for message ${asstMsgId}: " + ex.message, ex)
    }
}

def newWe = ec.entity.makeValue("mantle.work.effort.WorkEffort")
newWe.workEffortName = workEffortName
newWe.workEffortTypeEnumId = workEffortTypeEnumId
newWe.parentWorkEffortId = parentWorkEffortId ?: null
newWe.statusId = "WeInPlanning"
newWe.setSequencedIdPrimary()
newWe.create()

context.workEffortId = newWe.workEffortId

if (messageId) {
    def msg = ec.entity.find("org.moqui.ai.discussion.AgiMessage").condition("messageId", messageId).one()
    if (msg) {
        msg.promotedWorkEffortId = newWe.workEffortId
        msg.update()
    }
}
if (discussionId) {
    def disc = ec.entity.find("org.moqui.ai.discussion.AgiDiscussion").condition("discussionId", discussionId).one()
    if (disc) {
        disc.promotedWorkEffortId = newWe.workEffortId
        disc.statusId = "AgdStatusPromoted"
        disc.update()
    }
}

// 1. Idempotency Guard: Check if active subplan children already exist under parentMessageId def existingChildren = ec.entity.find("org.moqui.ai.discussion.AgiMessage") .condition("discussionId", discussionId) .condition("parentMessageId", parentMessageId) .condition("statusId", "not-equals", "AmsArchived") .condition("senderRoleEnumId", "not-equals", "AsrAssistant") .list()
if (existingChildren && !existingChildren.isEmpty()) { // Check if any existing child is already a subplan boolean hasSubplans = existingChildren.any { child -> child.stagedPayloadId != null } if (hasSubplans) { ec.message.addError("Subplans are already instantiated under turn #${parentMessageId}. Archive the existing subplan branch before re-instantiating.") return } }
def createdNodes = [] String batchRunId = java.util.UUID.randomUUID().toString()
// targetComponent resides on the AgiDiscussion container entity def disc = ec.entity.find("org.moqui.ai.discussion.AgiDiscussion") .condition("discussionId", discussionId) .one() String comp = disc?.targetComponent ?: "nursinghome"
// Fetch parent message to inherit targetArtifactUri if present def parentMsg = ec.entity.find("org.moqui.ai.discussion.AgiMessage") .condition("messageId", parentMessageId) .one() String parentArtUri = parentMsg?.targetArtifactUri ?: disc?.targetArtifactUri ?: ""
subplans.each { sp -> String rawTitle = sp.title ?: "Subplan" String subplanTitle = sp.phase ? "${sp.phase}:${rawTitle}" : rawTitle String nodeTreeLabel = "📋 " + subplanTitle
String subplanBody = groovy.json.JsonOutput.prettyPrint(groovy.json.JsonOutput.toJson(sp))
StringBuilder mdBody = new StringBuilder() mdBody.append("#### ${subplanTitle}\n\n") if (sp.description) { mdBody.append("${sp.description.trim()}\n\n") }
if (sp.entities && !sp.entities.isEmpty()) { mdBody.append("**Target Entities:**\n") sp.entities.each { mdBody.append("* `${it}`\n") } mdBody.append("\n") }
if (sp.services && !sp.services.isEmpty()) { mdBody.append("**Required Services:**\n") sp.services.each { mdBody.append("* `${it}`\n") } mdBody.append("\n") }
if (sp.xmlScreens && !sp.xmlScreens.isEmpty()) { mdBody.append("**Target XML Screens:**\n") sp.xmlScreens.each { mdBody.append("* `${it}`\n") } mdBody.append("\n") }
// 1. Create child AgiMessage turn def newMsg = ec.entity.makeValue("org.moqui.ai.discussion.AgiMessage") newMsg.discussionId = discussionId newMsg.parentMessageId = parentMessageId newMsg.senderRoleEnumId = "AsrUser" newMsg.partyId = ec.user.userId ?: "User" newMsg.statusId = "AmsActive" newMsg.targetArtifactUri = parentArtUri newMsg.entryDate = ec.user.nowTimestamp newMsg.setSequencedIdPrimary() newMsg.create()
ec.entity.makeValue("org.moqui.ai.discussion.AgiMessageContent") .set("messageId", newMsg.messageId) .set("contentSeqId", "1") .set("contentTypeEnumId", "mctMarkdown") .set("title", nodeTreeLabel) .set("bodyText", mdBody.toString()) .create()
// Record batch facet on message ec.entity.makeValue("org.moqui.ai.discussion.AgiMessageFacet") .set("messageId", newMsg.messageId) .set("facetKey", "batchRunId") .set("facetValue", batchRunId) .set("facetTypeEnumId", "AftDirective") .set("isInheritable", "N") .setSequencedIdPrimary() .create()
// 2. Create corresponding AgiPayload def newPayload = ec.entity.makeValue("org.moqui.ai.payload.AgiPayload") newPayload.modeEnumId = "AamPlan" newPayload.statusId = "PlsDraft" newPayload.targetComponent = comp newPayload.artifactUri = parentArtUri newPayload.discussionId = discussionId newPayload.messageId = newMsg.messageId newPayload.title = subplanTitle newPayload.userPromptText = sp.description ?: subplanTitle newPayload.payloadJsonData = subplanBody newPayload.createdDate = ec.user.nowTimestamp newPayload.setSequencedIdPrimary() newPayload.create()
// Link stagedPayloadId back to child AgiMessage newMsg.stagedPayloadId = newPayload.agiPayloadId newMsg.update()
createdNodes.add([ nodeKey : "msg_" + newMsg.messageId, id : newMsg.messageId, messageId : newMsg.messageId, discussionId : discussionId, parentMessageId : parentMessageId, label : nodeTreeLabel, senderRoleEnumId: "AsrUser", mode : "plan", stagedPayloadId : newPayload.agiPayloadId, statusId : "AmsActive", entryDate : newMsg.entryDate?.toString(), children : [] ]) }
// Increment discussion container message count if (disc) { disc.messageCount = (disc.messageCount ?: 0) + subplans.size() disc.lastActivityDate = ec.user.nowTimestamp disc.update() }
context.createdSubplanNodes = createdNodes context.batchRunId = batchRunId

int count = 0

def archiveMessageRecursive
archiveMessageRecursive = { String targetMsgId ->
    def msg = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
        .condition("messageId", targetMsgId)
        .one()
    if (msg && msg.statusId != "AmsArchived") {
        msg.statusId = "AmsArchived"
        msg.update()
        count++

        if (msg.stagedPayloadId) {
            def payload = ec.entity.find("org.moqui.ai.payload.AgiPayload")
                .condition("agiPayloadId", msg.stagedPayloadId)
                .one()
            if (payload && payload.statusId == "PlsDraft") {
                payload.statusId = "PlsArchived"
                payload.update()
            }
        }

        def children = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
            .condition("parentMessageId", targetMsgId)
            .list()
        children.each { child ->
            archiveMessageRecursive(child.messageId as String)
        }
    }
}

if (messageId) {
    archiveMessageRecursive(messageId as String)
} else if (discussionId) {
    def disc = ec.entity.find("org.moqui.ai.discussion.AgiDiscussion")
        .condition("discussionId", discussionId)
        .one()
    if (disc) {
        disc.statusId = "AgdStatusArchived"
        disc.update()
        count++

        def rootMessages = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
            .condition("discussionId", discussionId)
            .condition("parentMessageId", null)
            .list()
        rootMessages.each { rMsg ->
            archiveMessageRecursive(rMsg.messageId as String)
        }
    }
}

context.archivedCount = count

int count = 0
messageIds.each { mId ->
    def msg = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
        .condition("messageId", mId)
        .one()
    if (msg && msg.statusId != "AmsArchived") {
        msg.statusId = "AmsArchived"
        msg.update()
        count++

        if (msg.stagedPayloadId) {
            def payload = ec.entity.find("org.moqui.ai.payload.AgiPayload")
                .condition("agiPayloadId", msg.stagedPayloadId)
                .one()
            if (payload && payload.statusId == "PlsDraft") {
                payload.statusId = "PlsArchived"
                payload.update()
            }
        }
    }
}
context.rolledBackCount = count

int count = 0

def restoreMessageRecursive
restoreMessageRecursive = { String targetMsgId ->
    def msg = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
        .condition("messageId", targetMsgId)
        .one()
    if (msg && msg.statusId == "AmsArchived") {
        msg.statusId = "AmsActive"
        msg.update()
        count++

        if (msg.stagedPayloadId) {
            def payload = ec.entity.find("org.moqui.ai.payload.AgiPayload")
                .condition("agiPayloadId", msg.stagedPayloadId)
                .one()
            if (payload && payload.statusId == "PlsArchived") {
                payload.statusId = "PlsDraft"
                payload.update()
            }
        }

        def children = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
            .condition("parentMessageId", targetMsgId)
            .list()
        children.each { child ->
            restoreMessageRecursive(child.messageId as String)
        }
    }
}

if (messageId) {
    restoreMessageRecursive(messageId as String)

    def currentMsg = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
        .condition("messageId", messageId)
        .one()
    while (currentMsg?.parentMessageId) {
        def parent = ec.entity.find("org.moqui.ai.discussion.AgiMessage")
            .condition("messageId", currentMsg.parentMessageId)
            .one()
        if (parent && parent.statusId == "AmsArchived") {
            parent.statusId = "AmsActive"
            parent.update()
            count++
        }
        currentMsg = parent
    }
} else if (discussionId) {
    def disc = ec.entity.find("org.moqui.ai.discussion.AgiDiscussion")
        .condition("discussionId", discussionId)
        .one()
    if (disc) {
        disc.statusId = "AgdStatusActive"
        disc.update()
        count++
    }
}

context.restoredCount = count
